package com.qboix.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import org.json.*;import java.util.*;
public class GpsTrackingService extends Service implements LocationListener{
 public static final String ACTION="com.qboix.app.GPS_UPDATE",START="START",PAUSE="PAUSE",RESUME="RESUME",FINISH="FINISH";private static final String CHANNEL="qboix_gps_tracking";
 private LocationManager manager;private final ArrayList<Location> points=new ArrayList<>();private Location previous;private double metres;private long started,pausedMs,pauseAt;private boolean active,paused;private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable ticker=new Runnable(){public void run(){broadcast();if(active&&!paused)handler.postDelayed(this,1000);}};
 public void onCreate(){super.onCreate();manager=(LocationManager)getSystemService(LOCATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Q-BOIX GPS tracking",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}}
 public int onStartCommand(Intent i,int flags,int id){String a=i==null?null:i.getAction();if(START.equals(a))startRun();else if(PAUSE.equals(a))pauseRun();else if(RESUME.equals(a))resumeRun();else if(FINISH.equals(a))finishRun();return START_STICKY;}
 private Notification notification(String msg){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setContentTitle("Q-BOIX running").setContentText(msg).setSmallIcon(android.R.drawable.ic_menu_mylocation).setOngoing(true).build();}
 private void startRun(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return;}try{if(!manager.isProviderEnabled(LocationManager.GPS_PROVIDER)){send("Turn on GPS/location.");stopSelf();return;}points.clear();previous=null;metres=0;pausedMs=0;started=SystemClock.elapsedRealtime();active=true;paused=false;startForeground(7101,notification("Recording your run"));manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this,Looper.getMainLooper());Location l=manager.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l!=null)onLocationChanged(l);handler.removeCallbacks(ticker);handler.post(ticker);send("GPS recording. Screen may be locked.");}catch(Exception e){send("Could not start GPS tracking.");stopSelf();}}
 private void pauseRun(){if(!active||paused)return;paused=true;pauseAt=SystemClock.elapsedRealtime();manager.removeUpdates(this);handler.removeCallbacks(ticker);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7101,notification("Run paused"));broadcast();}
 private void resumeRun(){if(!active||!paused)return;pausedMs+=SystemClock.elapsedRealtime()-pauseAt;paused=false;try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this,Looper.getMainLooper());handler.post(ticker);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7101,notification("Recording your run"));broadcast();}catch(SecurityException e){send("Location permission required.");}}
 private void finishRun(){if(!active){stopForeground(true);stopSelf();return;}active=false;manager.removeUpdates(this);handler.removeCallbacks(ticker);long end=paused?pauseAt:SystemClock.elapsedRealtime();int sec=(int)Math.max(1,(end-started-pausedMs)/1000);double avg=metres>0?sec/(metres/1000):0;JSONArray route=new JSONArray();for(Location p:points){JSONObject o=new JSONObject();try{o.put("lat",p.getLatitude());o.put("lon",p.getLongitude());o.put("accuracy",p.getAccuracy());route.put(o);}catch(Exception ignored){}}WorkoutStore.saveRun(this,metres,sec,avg,route);send("Run saved offline.");stopForeground(true);stopSelf();}
 public void onLocationChanged(Location l){if(!active||paused||l==null||!l.hasAccuracy()||l.getAccuracy()>35)return;if(previous!=null){float d=previous.distanceTo(l);long sec=Math.max(1,(l.getTime()-previous.getTime())/1000);if(d<1.5)return;if(d/sec>8.5)return;metres+=d;}previous=new Location(l);points.add(new Location(l));broadcast();}
 private void broadcast(){long now=paused?pauseAt:SystemClock.elapsedRealtime();int sec=active?(int)Math.max(0,(now-started-pausedMs)/1000):0;Intent i=new Intent(ACTION);i.setPackage(getPackageName());i.putExtra("distance",metres);i.putExtra("seconds",sec);i.putExtra("pace",metres>=20?sec/(metres/1000):0);i.putExtra("active",active);i.putExtra("paused",paused);i.putExtra("message",paused?"Run paused.":"GPS recording • "+points.size()+" route points");sendBroadcast(i);}
 private void send(String m){broadcast();Intent i=new Intent(ACTION);i.setPackage(getPackageName());i.putExtra("message",m);i.putExtra("active",active);i.putExtra("paused",paused);i.putExtra("distance",metres);i.putExtra("seconds",0);sendBroadcast(i);}
 public void onDestroy(){manager.removeUpdates(this);handler.removeCallbacks(ticker);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}